import{home,photographersPage}from'./experience.js';
import{icon}from'./icons.js';import{service,api,image,date,escape}from'./service.js';import{auth}from'./auth.js';import{selection}from'./selection.js';import{photoGrid,toolbar,bindGallery}from'./gallery.js';import{openViewer}from'./viewer.js';import{openSlideshow}from'./slideshow.js';import{downloadPhotos}from'./downloads.js';import{adminContent,bindAdmin}from'./admin.js';import{openShareManager}from'./sharelinks.js';import{initFaq}from'./faq.js';
const isStaff=u=>['owner','admin'].includes(u?.role);
const app=document.getElementById('app');const admin=location.pathname.includes('admin');let page=admin?'Overview':'Photos',eventId=null,album=null,only='',person=null,filter='Tous',query='';
// ----- Retour là où l'on était : sur téléphone le navigateur recharge souvent l'onglet (retour d'une autre appli, mémoire pleine…).
// La page, la galerie ouverte, le filtre, la recherche et la position de défilement sont gardés et rétablis. -----
const navKey=()=>`kp-nav:${admin?'a':'c'}:${auth.session()?.id||''}`;
let navRestored=false,navScroll=0;
function saveNav(){if(preview||!auth.session())return;try{localStorage.setItem(navKey(),JSON.stringify({t:Date.now(),page,eventId,album,only,filter,query,y:Math.round(window.scrollY)}))}catch{}}
function restoreNav(){if(preview||navRestored)return;navRestored=true;try{const o=JSON.parse(localStorage.getItem(navKey())||'null');if(!o||Date.now()-o.t>6*3600e3)return;if(!(labels.includes(o.page)||o.page==='Profile'))return;if(o.eventId&&!service.data.events.some(e=>e.id===o.eventId))o.eventId=null;page=o.page;eventId=o.eventId;album=o.album||null;only=o.only||'';filter=o.filter||'Tous';query=o.query||'';navScroll=o.y||0}catch{}}
function restoreScroll(){if(!navScroll)return;const y=navScroll;navScroll=0;const go=()=>window.scrollTo(0,y);requestAnimationFrame(go);setTimeout(go,400);setTimeout(go,1200)}
window.addEventListener('scroll',()=>{clearTimeout(window.__navT);window.__navT=setTimeout(saveNav,300)},{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveNav()});window.addEventListener('pagehide',saveNav);const labels=admin?['Overview','Clients','Statistics','Billing','Events','Selections','Photos','Albums','Comments','Announcements','Team','Emails','Downloads','Storage','Settings']:['Photos','Events','Favorites','Comments','Downloads','Photographers'];const icons={Statistics:'up',Billing:'star',Photographers:'users',Overview:'grid',Clients:'users',Photos:'photos',Events:'events',Albums:'albums',Favorites:'heart',Downloads:'download',Storage:'albums',Settings:'settings',Profile:'users',Team:'shield',Emails:'mail',Comments:'chat',Announcements:'bell',Selections:'check'};
let preview=null;const me=()=>preview?.client||auth.session()||{name:'',email:''};const initials=n=>n.split(/\s+/).filter(Boolean).map(w=>w[0]).join('').slice(0,2).toUpperCase();
const avatarHtml=(u,cls='')=>u?.avatar?`<img class="avatar ${cls}" src="${escape(u.avatar)}" alt="">`:`<span class="avatar ${cls}">${escape(initials(u?.name||''))}</span>`;
const fr={Overview:'Aperçu',Clients:'Clients',Photos:admin?'Importer':'Accueil',Events:admin?'Événements':'Mes galeries',Albums:admin?'Photos':'Albums',Favorites:'Favoris',Downloads:'Téléchargements',Statistics:'Statistiques',Billing:'Administration',Photographers:'Mes photographes',Storage:'Stockage',Settings:'Réglages',Profile:'Profil',Team:'Équipe',Emails:'E-mails',Comments:'Commentaires',Announcements:'Notifications',Selections:'Sélections'};
let focusMode=false;let compact=false;export // ----- Notifications : cloche avec pastille « non lu », liste cliquable -----
const notifs=()=>service.data.notifications||[];
const seenAt=()=>auth.session()?.notificationsSeenAt||'';
const unreadCount=()=>service.readOnly?0:notifs().filter(n=>n.date>seenAt()).length;
function bellButton(){const n=unreadCount();return `<button class="icon notif-bell" id="notifications" aria-label="Notifications${n?` : ${n} nouvelle${n>1?'s':''}`:''}">${icon('bell')}${n?`<span class="notif-dot">${n>9?'9+':n}</span>`:''}</button>`}
const NOTIF_ICONS={gallery:'photos',photos:'camera',comment:'chat',expiry:'clock',selection:'check',signup:'users',announcement:'bell'};
function ago(iso){const s=(Date.now()-Date.parse(iso))/1000;if(s<60)return'à l’instant';if(s<3600)return`il y a ${Math.floor(s/60)} min`;if(s<86400)return`il y a ${Math.floor(s/3600)} h`;if(s<172800)return'hier';if(s<604800)return`il y a ${Math.floor(s/86400)} jours`;return new Date(iso).toLocaleDateString('fr-FR',{day:'numeric',month:'long'})}
function openNotifications(){const list=notifs();const seen=seenAt();modal('Notifications',list.length?`<ul class="notif-list">${list.map((n,i)=>`<li><button class="notif-item${n.date>seen?' is-new':''}" data-notif="${i}"><span class="notif-icon is-${n.kind}">${icon(NOTIF_ICONS[n.kind]||'bell')}</span><span class="notif-text"><strong>${escape(n.title)}</strong>${n.text?`<small>${escape(n.text)}</small>`:''}<time datetime="${n.date}">${ago(n.date)}</time></span></button></li>`).join('')}</ul>`:`<div class="notif-empty">${icon('bell')}<p>Rien de nouveau pour l’instant.</p><small>Vous serez prévenu ici dès qu’une galerie, une photo ou une réponse arrive.</small></div>`);
const host=document.getElementById('overlays');host.querySelectorAll('[data-notif]').forEach(b=>b.onclick=()=>{const n=list[b.dataset.notif];host.innerHTML='';openNotification(n)});
// Ouvrir la cloche marque tout comme vu (la pastille disparaît ; la liste garde le repère « nouveau » jusqu'à la fermeture).
if(unreadCount())api('/api/auth/notifications/seen',{method:'POST'}).then(r=>{if(auth.session())auth.session().notificationsSeenAt=r.seenAt;document.querySelector('#notifications .notif-dot')?.remove()}).catch(()=>{})}
function openNotification(n){if(n.kind==='announcement')return openAnnouncement(n);if(admin){navigate(n.kind==='comment'?'Comments':n.kind==='signup'?'Clients':n.kind==='selection'?'Selections':'Events');return}
if(!n.eventId||!service.data.events.some(e=>e.id===n.eventId))return toast('Cette galerie n’est plus disponible.');eventId=n.eventId;album=null;person=null;selection.clear();render();window.scrollTo(0,0);
if(n.photoId){const photos=shownPhotos();const i=photos.findIndex(p=>p.id===n.photoId);if(i>=0)openViewer(photos,i,toast,render)}}
// Message écrit par le studio : texte complet, puis la galerie liée s'il y en a une.
function openAnnouncement(n){modal(n.title,`<div class="notice-body"><p>${escape(n.body||n.text||'').replace(/\r?\n/g,'<br>')}</p><time datetime="${n.date}">${ago(n.date)}</time></div>${n.eventId&&!admin?`<div class="actions"><button class="btn primary" id="notice-open">${icon('photos')} Voir la galerie</button></div>`:''}`);document.getElementById('notice-open')?.addEventListener('click',()=>{document.getElementById('overlays').innerHTML='';openNotification({...n,kind:'gallery'})})}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.style.display='block';clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>el.style.display='none',4000)}
const brand=()=>`<div class="brand"><img class="brandmark" src="/logo/kentrapix-icon.svg" alt="" width="40" height="40"><div><strong>Kentra<span>Pix</span></strong></div></div>`;
function navigate(p){if(admin&&!labels.includes(p)&&p!=='Profile')p='Overview';focusMode=false;page=p;eventId=null;album=null;only='';person=null;query='';selection.clear();render();window.scrollTo(0,0)}
function events(){return service.data.events.filter(e=>(admin||e.published)&&(!query||[e.name,e.type,e.date].join(' ').toLowerCase().includes(query.toLowerCase())))}
// ----- Photos pas prêtes : « pas encore prêtes » (jamais eu de photos) ou « retirées / mises à jour » (il y en avait, il n'y en a plus) -----
const seenKey=()=>`kp-seen:${auth.session()?.id||''}`;
function readiness(e){if(admin||preview)return'ready';const n=service.photos(e.id).length;let m={};try{m=JSON.parse(localStorage.getItem(seenKey())||'{}')}catch{}if(n>0){if(m[e.id]!==n){m[e.id]=n;try{localStorage.setItem(seenKey(),JSON.stringify(m))}catch{}}return'ready'}return m[e.id]>0?'removed':'soon'}
function notReady(e){const first=me().name.split(' ')[0];return readiness(e)==='removed'?`<div class="empty not-ready">${icon('clock')}<h2>Vos photos sont en cours de mise à jour</h2><p class="small">Les photos de cette galerie ne sont plus disponibles pour le moment. Votre photographe les prépare à nouveau : revenez bientôt, vous gardez le même accès.</p></div>`:`<div class="empty not-ready">${icon('camera')}<h2>Bonjour ${escape(first)}, vos photos ne sont pas encore prêtes</h2><p class="small">Votre photographe termine la retouche${e.photographer?` (${escape(e.photographer)})`:''}. Dès qu’elles seront en ligne, vous les verrez ici et vous serez prévenu par e-mail.</p></div>`}
function cards(list){return `<div class="events-grid">${list.map((e,i)=>`<button class="event-card" data-event="${e.id}" style="--i:${Math.min(i,10)}"><div class="event-cover">${e.cover?`<img src="${escape(e.cover)}" alt="${escape(e.name)}" loading="lazy">`:''}<span class="badge">${escape(e.type)}</span>${e.selectionMode?`<span class="badge is-proof">${icon('check')} Sélection</span>`:''}${readiness(e)==='ready'?'':`<span class="badge is-soon">${icon('clock')} ${readiness(e)==='removed'?'Mise à jour':'Bientôt'}</span>`}<div class="event-overlay"><h3>${escape(e.name)}</h3><p>${date(e.date)} · ${readiness(e)==='ready'?`${service.photos(e.id).length} photos`:readiness(e)==='removed'?'Photos en mise à jour':'Photos pas encore prêtes'}</p>${e.photographer?`<p class="ev-by">${icon('camera')} Par ${escape(e.photographer)}</p>`:''}${e.unlockNumbers!=null&&e.openPhotos<e.totalPhotos?`<p class="ev-by">${icon('lock')} ${e.openPhotos} photo${e.openPhotos>1?'s':''} débloquée${e.openPhotos>1?'s':''} sur ${e.totalPhotos}</p>`:''}</div></div></button>`).join('')}</div>`}
// Photos que le photographe n'a pas (encore) débloquées : bandeau explicatif en haut de la galerie.
const lockReason=e=>e.lockReason||'Votre photographe n’a pas encore débloqué les autres photos.';
function lockBanner(e){if(e.unlockNumbers==null||e.openPhotos>=e.totalPhotos)return'';const n=e.openPhotos;const list=e.unlockNumbers&&e.unlockNumbers.length<=40?` (n° ${escape(e.unlockNumbers)})`:'';return `<div class="lock-banner" role="note">${icon('lock')}<div><strong>${n?`${n} photo${n>1?'s':''} débloquée${n>1?'s':''} sur ${e.totalPhotos}${list}`:`${e.totalPhotos} photos en attente`}</strong><span>${escape(lockReason(e))}</span></div></div>`}
function typeChips(){const types=[...new Set(events().map(e=>e.type))];return types.length>1?`<div class="type-chips" role="group" aria-label="Catégories"><button class="chip ${filter==='Tous'?'active':''}" data-filter="Tous">Toutes</button>${types.map(t=>`<button class="chip ${filter===t?'active':''}" data-filter="${escape(t)}">${escape(t)} <small>${events().filter(e=>e.type===t).length}</small></button>`).join('')}</div>`:''}
function empty(title,text){return `<div class="empty">${icon('photos')}<h2>${title}</h2>${text?`<p class="small">${text}</p>`:''}</div>`}
function clientContent(){if(page==='Photos'&&!eventId&&!query)return home(events(),cards,me().name.split(' ')[0],readiness);if(eventId){const e=service.data.events.find(e=>e.id===eventId);return `<div class="gallery-header"><button class="text-link" id="back">← ${fr.Events}</button><h1>${escape(e.name)}</h1>${e.photographer?`<p class="gallery-by">${icon('camera')} Photos de <strong>${escape(e.photographer)}</strong></p>`:''}${lockBanner(e)}${expiryNote(e)}<div class="gallery-actions"${service.photos(e.id).length?'':' hidden'}><div class="ga-main">${e.selectionMode?'':`<button class="btn primary ga-primary" id="event-download">${icon('download')}<span class="ga-label">Tout télécharger</span></button>`}<button class="btn${e.selectionMode?' primary ga-primary':' ga-round'}" id="slideshow" title="Diaporama" aria-label="Diaporama">${icon('play')}<span class="ga-label">Diaporama</span></button>${service.data.permissions.sharing&&!preview?`<button class="btn ga-round" id="share-event" title="Partager avec la famille" aria-label="Partager avec la famille">${icon('share')}<span class="ga-label">Partager</span></button>`:''}</div><div class="ga-tools" role="group" aria-label="Affichage">${e.selectionMode?'':`<button class="ga-tool${selection.active?' is-on':''}" id="select" aria-pressed="${selection.active}" title="Sélectionner des photos">${icon('check')}<span>Sélectionner</span></button>`}<button class="ga-tool${compact?' is-on':''}" id="density" aria-pressed="${compact}" title="Changer la taille des photos">${icon('grid')}<span>Taille</span></button><button class="ga-tool${focusMode?' is-on':''}" id="focus-mode" aria-pressed="${focusMode}" title="Mode immersion">${icon('photos')}<span>Immersion</span></button><button class="ga-tool" id="event-more" title="Détails de la galerie">${icon('more')}<span>Détails</span></button></div></div><div class="filterbar"${service.photos(e.id).length?'':' hidden'}><button class="chip ${!album&&!only?'active':''}" data-album="">Toutes <small>${service.photos(eventId).length}</small></button>${[...new Set(service.photos(eventId).map(p=>p.album))].map(a=>`<button class="chip ${album===a&&!only?'active':''}" data-album="${escape(a)}">${escape(a)} <small>${service.photos(eventId).filter(p=>p.album===a).length}</small></button>`).join('')}<button class="chip ${only==='fav'?'active':''}" data-only="fav">Favoris <small>${service.photos(eventId).filter(p=>service.data.favorites.includes(p.id)).length}</small></button>${e.selectionMode?`<button class="chip ${only==='sel'?'active':''}" data-only="sel">Sélectionnées <small>${service.picks(e.id).length}</small></button>`:''}</div></div>${e.selectionMode?pickPanel(e):''}${toolbar()}${shownPhotos(true).length?photoGrid(shownPhotos(true)):service.photos(e.id).length?empty('Aucune photo ici'):notReady(e)}`}
if(page==='Favorites')return `<div class="greeting"><h1>Favoris</h1></div>${toolbar()}${shownPhotos().length?photoGrid(shownPhotos()):empty('Aucun favori pour l’instant','Touchez le cœur sur une photo pour la retrouver ici.')}`;
if(page==='Albums'){const groups=service.data.events.filter(e=>admin||e.published).flatMap(e=>[...new Set(service.photos(e.id).map(p=>p.album))].map(a=>({e,a,photos:service.photos(e.id).filter(p=>p.album===a)}))).filter(g=>!query||g.a.toLowerCase().includes(query.toLowerCase())||g.e.name.toLowerCase().includes(query.toLowerCase()));return `<div class="greeting"><h1>Albums</h1></div><div class="events-grid">${groups.map(g=>`<button class="event-card" data-open-album="${escape(g.a)}" data-parent="${g.e.id}"><div class="event-cover"><img loading="lazy" src="${g.photos[0].thumb||g.photos[0].preview}" alt="${escape(g.a)}"></div><div class="event-info"><h3>${escape(g.a)}</h3><p>${escape(g.e.name)} · ${g.photos.length} photos</p></div></button>`).join('')}</div>`}
if(page==='Comments')return `<div class="greeting"><h1>Commentaires</h1><p class="greeting-sub">Les mots laissés par votre famille sous les photos que vous avez partagées.</p></div><div id="family-filters"></div><div id="family-list"><div class="empty">${icon('chat')}<h2>Chargement…</h2></div></div>`;
if(page==='Photographers')return photographersPage(service.data.photographers);
if(page==='Downloads')return `<div class="greeting"><h1>Téléchargements</h1></div>${service.data.downloads.length?`<div class="settings">${service.data.downloads.map(d=>`<div class="row between"><div><strong>${escape(d.name)}</strong><p class="small">${new Date(d.date).toLocaleString('fr-FR')} · ${d.count} photos</p></div>${icon('download')}</div>`).join('')}</div>`:empty('Aucun téléchargement','Les photos que vous téléchargez apparaîtront ici.')}`;
if(page==='Profile'){const u=me();const role=u.role==='owner'?'Propriétaire':isStaff(u)?'Administrateur':'Client';return `<div class="profile-page"><section class="profile-hero"><div class="profile-cover"></div><div class="profile-id"><div class="profile-avatar">${avatarHtml(u,'xl')}${preview?'':`<label class="profile-avatar-edit" for="avatar-file" title="${u.avatar?'Changer la photo':'Ajouter une photo'}" aria-label="${u.avatar?'Changer la photo':'Ajouter une photo'}">${icon('camera')}</label><input id="avatar-file" type="file" accept="image/*" hidden>`}</div><div class="profile-meta"><span class="profile-role">${role}</span><h1>${escape(u.name)}</h1><p>${[escape(u.email||''),escape(u.phone||'')].filter(Boolean).join(' · ')}</p></div>${preview?'':`<div class="row profile-photo-actions"><label class="btn sm" for="avatar-file">${icon('camera')} ${u.avatar?'Changer la photo':'Ajouter une photo'}</label>${u.avatar?`<button class="btn sm" id="avatar-remove">${icon('trash')} Retirer</button>`:''}</div>`}</div></section>${preview?'':`<div class="profile-grid"><section class="settings profile-panel"><header><h2>Informations personnelles</h2><p class="small">Ces informations apparaissent sur vos galeries et vos e-mails.</p></header><form id="profile-form" class="profile-form"><label>Nom complet<input name="name" required maxlength="120" autocomplete="name" value="${escape(u.name)}"></label><label>Téléphone<input name="phone" type="tel" maxlength="40" autocomplete="tel" value="${escape(u.phone||'')}"></label><label class="full">E-mail<input value="${escape(u.email)}" disabled><small class="field-hint">L’adresse e-mail sert à vous connecter et ne peut pas être modifiée ici.</small></label>${isStaff(u)?`<label class="full">Nom d’expéditeur des e-mails<input name="senderName" maxlength="80" value="${escape(u.senderName||'')}" placeholder="${escape(u.name)}"><small class="field-hint">Vos clients verront ce nom dans leur boîte mail. Exemple : ${escape(u.name)} Photography</small></label><label>WhatsApp<input name="whatsapp" type="tel" maxlength="40" value="${escape(u.whatsapp||'')}" placeholder="${escape(u.phone||'+509…')}"></label><label>Instagram<input name="instagram" maxlength="80" value="${escape(u.instagram||'')}" placeholder="@votrestudio"></label><label class="full">Site web<input name="website" maxlength="200" value="${escape(u.website||'')}" placeholder="www.votresite.com"></label><label class="full">Adresse du studio<input name="address" maxlength="200" value="${escape(u.address||'')}"></label><label class="full">Présentation<textarea name="bio" rows="3" maxlength="500" placeholder="Quelques mots pour vos clients…">${escape(u.bio||'')}</textarea><small class="field-hint">Votre nom, téléphone, e-mail et ces informations sont montrés à vos clients dans « Mon photographe ».</small></label><label class="full">Mon code d’accès<input name="accessCode" maxlength="4" minlength="2" pattern="[A-Za-z0-9]{2,4}" autocomplete="off" spellcheck="false" value="${escape(u.accessCode||'')}" style="text-transform:uppercase;letter-spacing:.25em;font-weight:700"><small class="field-hint">Donnez ce code à vos clients (2 à 4 lettres ou chiffres). Quand ils créent leur compte, ils le saisissent et deviennent vos clients : vous seul les voyez.</small></label>`:''}<div class="row profile-save"><button class="btn primary">${icon('check')} Enregistrer</button></div></form></section><div class="profile-side"><section class="settings profile-panel"><header><h2>Apparence</h2><p class="small">Choisissez le thème de l’application sur cet appareil.</p></header>${themeSwitch()}</section><section class="settings profile-panel"><header><h2>Sécurité</h2><p class="small">Gérez l’accès à votre compte.</p></header><button class="profile-action" id="change-password">${icon('key')}<span><strong>Mot de passe</strong><small>Changer votre mot de passe</small></span></button>${isStaff(u)?`<button class="profile-action" id="change-studio">${icon('shield')}<span><strong>Mot de passe du studio</strong><small>Changer le mot de passe demandé à l’ouverture du studio</small></span></button>`:''}<button class="profile-action danger" id="logout">${icon('logout')}<span><strong>Se déconnecter</strong><small>Fermer la session sur cet appareil</small></span></button></section></div></div>${installCard()}`}</div>`}
const list=events().filter(e=>filter==='Tous'||e.type===filter);if(page==='Events')return `<div class="greeting"><h1>Mes galeries</h1></div>${typeChips()}${list.length?cards(list):empty('Aucune galerie pour le moment','Votre photographe prépare vos photos. Vous serez prévenu dès que votre première galerie sera en ligne.')}`;
return `<div class="greeting"><h1>Recherche</h1></div>${list.length?cards(list):empty('Aucun résultat')}`}
// Mode sélection : compteur, saisie de numéros (« 3, 7, 12-15 »), envoi au studio.
function pickPanel(e){const ids=service.picks(e.id);const all=service.photos(e.id);const nums=all.filter(p=>ids.includes(p.id)).map(p=>p.number).sort((a,b)=>a-b);const sent=service.data.selections?.[e.id]?.submittedAt;const ro=service.readOnly;return `<section class="pick-panel"><div class="pick-head"><span class="pick-icon">${icon('check')}</span><div><strong>Choisissez vos photos</strong><p class="small">Touchez une photo ou entrez ses numéros. Les photos de cette galerie ne sont pas téléchargeables.</p></div><span class="pick-count"><b>${ids.length}</b>${e.selectionLimit?` / ${e.selectionLimit}`:''}</span></div>${e.selectionLimit?`<div class="pick-bar" role="progressbar" aria-valuemin="0" aria-valuemax="${e.selectionLimit}" aria-valuenow="${ids.length}"><i style="width:${Math.min(100,Math.round(ids.length/e.selectionLimit*100))}%"></i></div><p class="pick-bar-text">${ids.length} / ${e.selectionLimit} photos choisies${ids.length>e.selectionLimit?' — vous dépassez la limite':''}</p>`:`<p class="pick-bar-text">${ids.length} photo${ids.length>1?'s':''} choisie${ids.length>1?'s':''}</p>`}${ro?'':`<form id="pick-form" class="pick-form"><input id="pick-input" inputmode="numeric" autocomplete="off" placeholder="Ex. 3, 7, 12-15" aria-label="Numéros des photos"><button class="btn">${icon('plus')} Ajouter</button></form>`}${nums.length?`<p class="pick-list">N° ${nums.join(', ')}</p>`:''}<div class="pick-foot">${sent?`<span class="small">${icon('check')} Envoyée le ${new Date(sent).toLocaleString('fr-FR',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})}</span>`:'<span></span>'}${ro?'':`<div class="row">${ids.length?'<button class="btn" id="pick-clear">Tout retirer</button>':''}<button class="btn primary" id="pick-send" ${ids.length?'':'disabled'}>${icon('send')} ${sent?'Renvoyer ma sélection':'Envoyer ma sélection'}</button></div>`}</div></section>`}
// « 3, 7, 12-15 » -> [3, 7, 12, 13, 14, 15]
function parseNumbers(text){const out=[];for(const part of text.split(/[\s,;]+/).filter(Boolean)){const m=part.match(/^(\d+)(?:-(\d+))?$/);if(!m)throw Error(`« ${part} » n’est pas un numéro valide.`);const a=+m[1],b=m[2]?+m[2]:a;if(b-a>500)throw Error('Plage de numéros trop grande.');for(let n=Math.min(a,b);n<=Math.max(a,b);n++)out.push(n)}return out}
function bindPicks(){const e=service.data.events.find(e=>e.id===eventId);if(!e?.selectionMode)return;const form=document.getElementById('pick-form');if(form)form.onsubmit=async ev=>{ev.preventDefault();const input=document.getElementById('pick-input');try{const nums=parseNumbers(input.value);if(!nums.length)return;const byNum=new Map(service.photos(e.id).map(p=>[p.number,p.id]));const missing=nums.filter(n=>!byNum.has(n));const ids=nums.filter(n=>byNum.has(n)).map(n=>byNum.get(n));const p=service.setPicks(e.id,[...service.picks(e.id),...ids]);render();document.getElementById('pick-input')?.focus();await p;if(missing.length)toast(`N° ${missing.join(', ')} introuvable${missing.length>1?'s':''} dans cette galerie.`)}catch(err){toast(err.message);render()}};document.getElementById('pick-clear')?.addEventListener('click',()=>{service.setPicks(e.id,[]).catch(err=>{toast(err.message);render()});render()});document.getElementById('pick-send')?.addEventListener('click',()=>modal('Envoyer ma sélection',`<p>${service.picks(e.id).length} photo(s) choisie(s) dans « ${escape(e.name)} ».</p><label>Message pour le studio <span class="optional">(facultatif)</span><textarea name="note" maxlength="2000" placeholder="Ex. : album 30 x 30, tirages pour la famille…">${escape(service.data.selections?.[e.id]?.note||'')}</textarea></label>`,async v=>{const r=await api(`/api/client/events/${e.id}/selection/submit`,{method:'POST',body:{note:v.note}});Object.assign(service.data.selections[e.id],{note:v.note,submittedAt:r.submittedAt});toast(`Sélection envoyée : N° ${r.numbers.join(', ')}`);render()}))}
function shownPhotos(all=false){const allowed=new Set(events().map(e=>e.id));return service.data.photos.filter(p=>(all||!p.locked)&&allowed.has(p.eventId)&&(!eventId||p.eventId===eventId)&&(!album||p.album===album)&&(page!=='Favorites'||service.data.favorites.includes(p.id))&&(only!=='fav'||service.data.favorites.includes(p.id))&&(only!=='sel'||service.picks(p.eventId).includes(p.id))&&(!query||[p.filename,p.album,service.data.events.find(e=>e.id===p.eventId)?.name].join(' ').toLowerCase().includes(query.toLowerCase())))}
function render(){saveNav();document.body.classList.toggle('focus-mode',focusMode);document.body.classList.toggle('compact-photos',compact);const content=admin&&!['Downloads','Profile'].includes(page)?adminContent(page):clientContent();app.innerHTML=`<aside class="sidebar">${brand()}${admin?`<span class="badge" style="margin-top:18px;width:max-content">${auth.session().role==='owner'?'Propriétaire':'Admin'}</span>`:''}<nav class="nav" aria-label="Navigation principale">${labels.map(l=>`<button data-nav="${l}" class="${page===l?'active':''}">${icon(icons[l])}${fr[l]}${l==='Favorites'&&service.data.favorites.length?`<span class="small" style="margin-left:auto">${service.data.favorites.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot">${isStaff(auth.session())&&!preview?`<a class="text-link switch-space" href="${admin?'/client':'/admin'}">${icon(admin?'photos':'grid')} ${admin?'Mes photos':'Studio'}</a>`:''}<button class="sidebar-profile${page==='Profile'?' active':''}" id="profile-link" aria-label="Mon profil">${avatarHtml(me())}<span><strong>${escape(me().name)}</strong><small>Mon profil</small></span></button><button class="sidebar-logout" id="sidebar-logout">${icon('logout')} Se déconnecter</button><p>${installButton()}© ${new Date().getFullYear()} KentraPix. Tous droits réservés.<br><a href="/conditions" target="_blank" rel="noopener">Conditions d’utilisation</a></p></div></aside><div class="workspace"><header class="topbar"><div class="search">${icon('search')}<input id="search" aria-label="Rechercher" placeholder="Rechercher" value="${escape(query)}"></div><div class="row">${isStaff(auth.session())&&!preview&&admin?`<a class="icon mobile-only" href="/client" aria-label="Mes photos" title="Mes photos">${icon('photos')}</a>`:''}${installed()?'':`<button class="icon mobile-only" data-install aria-label="Installer l’application" title="Installer l’application">${icon('download')}</button>`}<button class="icon" id="theme-toggle" aria-label="Changer de thème" title="Mode clair / sombre">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button>${bellButton()}<span style="height:25px;border-left:1px solid var(--border);margin:0 10px"></span><button class="row" id="profile">${avatarHtml(me())}<span class="user-name small">${escape(me().name)}</span></button></div></header><main class="main">${preview?previewBanner():''}${content}</main></div><nav class="bottomnav" aria-label="Navigation mobile">${(admin?['Overview','Clients','Billing','Events','Photos',auth.session()?.role==='owner'?'Team':'Emails']:['Photos','Events','Favorites','Comments','Photographers','Profile']).map(l=>`<button class="${page===l?'active':''}" data-nav="${l}">${icon(icons[l])}<span>${(admin?{Billing:'Admin'}:{Photographers:'Photographes',Events:'Galeries',Comments:'Avis'})[l]||fr[l]}</span></button>`).join('')}${isStaff(auth.session())&&!preview&&!admin?`<a class="nav-switch" href="/admin">${icon('grid')}<span>Studio</span></a>`:''}</nav>`;bind()}
// Ajout d'un photographe par son code (page « Mes photographes »).
function bindPhotographers(){const f=document.getElementById('add-photographer-form');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('button');btn.disabled=true;try{const r=await api('/api/client/photographers',{method:'POST',body:{code:new FormData(f).get('code')}});service.data.photographers=r.photographers;toast(`${r.added} ajouté à vos photographes.`);render()}catch(err){toast(err.message)}finally{btn.disabled=false}}}
function bind(){bindPhotographers();document.querySelectorAll('[data-locked-photo]').forEach(t=>{const open=()=>{const e=service.data.events.find(x=>x.id===t.dataset.lockedEvent);modal('Photo verrouillée',`<p>${icon('lock')} <strong>Cette photo n’est pas encore disponible.</strong></p><p>${escape(e?lockReason(e):'Votre photographe ne l’a pas encore débloquée.')}</p>`)};t.onclick=open;t.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();open()}}});document.getElementById('surprise')?.addEventListener('click',()=>{const photos=shownPhotos();if(photos.length)openViewer(photos,Math.floor(Math.random()*photos.length),toast,render)});document.getElementById('density')?.addEventListener('click',()=>{compact=!compact;render()});document.getElementById('focus-mode')?.addEventListener('click',()=>{focusMode=!focusMode;render()});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));document.querySelectorAll('[data-event]').forEach(b=>{const open=()=>{eventId=b.dataset.event;album=null;only='';person=null;selection.clear();render();window.scrollTo(0,0)};b.onclick=open;b.onkeydown=e=>{if(e.key==='Enter')open()}});document.querySelectorAll('[data-open-album]').forEach(b=>b.onclick=()=>{eventId=b.dataset.parent;only='';album=b.dataset.openAlbum;render()});document.querySelectorAll('[data-only]').forEach(b=>b.onclick=()=>{only=only===b.dataset.only?'':b.dataset.only;album=null;selection.clear();render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-album]').forEach(b=>b.onclick=()=>{only='';album=b.dataset.album||null;selection.clear();render()});document.getElementById('search').oninput=e=>{const start=e.target.selectionStart;query=e.target.value;render();const input=document.getElementById('search');input.focus();input.setSelectionRange(start,start)};document.getElementById('profile').onclick=document.getElementById('profile-link').onclick=()=>navigate('Profile');document.getElementById('logout')?.addEventListener('click',()=>auth.signOut());document.getElementById('sidebar-logout').onclick=()=>auth.signOut();document.getElementById('notifications').onclick=openNotifications;document.getElementById('back')?.addEventListener('click',()=>navigate('Events'));document.getElementById('select')?.addEventListener('click',()=>{selection.active=!selection.active;render()});document.getElementById('slideshow')?.addEventListener('click',()=>{const p=shownPhotos(),e=service.data.events.find(e=>e.id===eventId);if(p.length)openSlideshow({photos:p,music:e?.music,title:e?.name})});document.getElementById('share-event')?.addEventListener('click',()=>openShare(service.data.events.find(e=>e.id===eventId)));document.getElementById('install-app')?.addEventListener('click',installApp);document.getElementById('event-download')?.addEventListener('click',()=>{const e=service.data.events.find(e=>e.id===eventId);if(!e.download||!service.data.permissions.event)return toast('Téléchargement désactivé.');downloadPhotos(shownPhotos(),toast,album?null:eventId)});document.getElementById('change-studio')?.addEventListener('click',()=>modal('Mot de passe du studio','<label>Mot de passe actuel du studio<input name="current" type="password" autocomplete="off" required></label><label>Nouveau mot de passe du studio<input name="password" type="password" autocomplete="new-password" minlength="6" required></label><label>Confirmer<input name="confirm" type="password" autocomplete="new-password" minlength="6" required></label>',async v=>{if(v.password!==v.confirm)throw Error('Les deux mots de passe ne correspondent pas.');await api('/api/auth/studio/password',{method:'POST',body:{current:v.current,password:v.password}});toast('Mot de passe du studio modifié.')}));document.getElementById('change-password')?.addEventListener('click',()=>modal('Changer mon mot de passe',passwordFields(),async v=>{if(v.newPassword!==v.confirm)throw Error('Les deux mots de passe ne correspondent pas.');await auth.changePassword(v.currentPassword,v.newPassword);toast('Mot de passe modifié.')}));document.getElementById('event-more')?.addEventListener('click',()=>{const e=service.data.events.find(e=>e.id===eventId);modal('Détails',`${e.description?`<p>${escape(e.description)}</p>`:''}<p>${[escape(e.location||''),date(e.date),service.photos(e.id).length+' photos'].filter(Boolean).join(' · ')}</p>`)});bindTheme();bindProfile();bindPicks();bindGallery(shownPhotos(),render,toast);if(!admin&&page==='Comments'&&!eventId)bindFamily();if(admin)bindAdmin(page,render,toast,modal,navigate,refresh)}
const previewBanner=()=>`<div class="preview-banner" role="status">${icon('users')}<span>Aperçu de l’espace de <strong>${escape(preview.client.name)}</strong>${preview.hiddenEvents?` · ${preview.hiddenEvents} galerie${preview.hiddenEvents>1?'s':''} non publiée${preview.hiddenEvents>1?'s':''} (invisible${preview.hiddenEvents>1?'s':''} pour le client)`:''}</span><a class="btn" href="/admin">Retour au studio</a></div>`;
function bindProfile(){const form=document.getElementById('profile-form');if(form)form.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));try{await auth.updateProfile(v.name,v.phone,v.senderName,{whatsapp:v.whatsapp,instagram:v.instagram,website:v.website,address:v.address,bio:v.bio});if(v.accessCode&&v.accessCode.toUpperCase()!==(auth.session()?.accessCode||''))await api('/api/auth/my-code',{method:'PATCH',body:{code:v.accessCode}}).then(()=>auth.load());toast('Profil enregistré.');render()}catch(err){toast(err.message)}};const file=document.getElementById('avatar-file');if(file)file.onchange=()=>{const f=file.files[0];file.value='';if(f)cropAvatar(f)};document.getElementById('avatar-remove')?.addEventListener('click',async()=>{try{await auth.removeAvatar();render()}catch(err){toast(err.message)}})}
async function refresh(){await service.load(admin?'admin':'client');render()}
const passwordFields=(current='Mot de passe actuel')=>`<label>${current}<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Nouveau mot de passe<input name="newPassword" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirmer<input name="confirm" type="password" autocomplete="new-password" minlength="8" required></label>`;
// Recadrage de la photo de profil : déplacer + zoomer dans un cercle, export carré 512 px.
function cropAvatar(f){const url=URL.createObjectURL(f);const img=new Image();const upload=async(blob)=>{await auth.setAvatar(blob);toast('Photo de profil mise à jour.');render()};img.onerror=()=>{URL.revokeObjectURL(url);upload(f).catch(err=>toast(err.message))};img.onload=()=>{const W=img.naturalWidth,H=img.naturalHeight;modal('Recadrer la photo',`<div class="crop-stage" id="crop-stage"><img src="${url}" alt="" draggable="false"></div><label class="crop-zoom">${icon('search')}<input id="crop-zoom" type="range" min="1" max="4" step="0.01" value="1" aria-label="Zoom"></label><p class="small crop-help">Faites glisser la photo pour centrer votre visage.</p>`,async()=>{const c=document.createElement('canvas');c.width=c.height=512;const k=st.scale();c.getContext('2d').drawImage(img,-st.x/k,-st.y/k,S()/k,S()/k,0,0,512,512);const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',0.92));URL.revokeObjectURL(url);await upload(new File([blob],'avatar.jpg',{type:'image/jpeg'}))});const stage=document.getElementById('crop-stage'),pic=stage.querySelector('img'),zoom=document.getElementById('crop-zoom');const S=()=>stage.clientWidth;const st={z:1,x:0,y:0,scale(){return S()/Math.min(W,H)*this.z}};const clamp=()=>{const k=st.scale();st.x=Math.min(0,Math.max(S()-W*k,st.x));st.y=Math.min(0,Math.max(S()-H*k,st.y))};const draw=()=>{clamp();const k=st.scale();pic.style.width=W*k+'px';pic.style.height=H*k+'px';pic.style.transform=`translate(${st.x}px,${st.y}px)`};const k0=st.scale();st.x=(S()-W*k0)/2;st.y=H>W?-(H*k0-S())*0.15:(S()-H*k0)/2;draw();const zoomTo=(z)=>{const k=st.scale(),cx=S()/2;const px=(cx-st.x)/k,py=(cx-st.y)/k;st.z=Math.min(4,Math.max(1,z));const n=st.scale();st.x=cx-px*n;st.y=cx-py*n;zoom.value=st.z;draw()};zoom.oninput=()=>zoomTo(Number(zoom.value));stage.onwheel=e=>{e.preventDefault();zoomTo(st.z*(e.deltaY<0?1.08:1/1.08))};let drag=null;stage.onpointerdown=e=>{drag={x:e.clientX-st.x,y:e.clientY-st.y};stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(!drag)return;st.x=e.clientX-drag.x;st.y=e.clientY-drag.y;draw()};stage.onpointerup=stage.onpointercancel=()=>{drag=null}};img.src=url}
// ----- Brouillon de fenêtre : ce qui est tapé dans une fenêtre (opts.draft) survit à un rechargement de la page (téléphone). -----
const draftKey=()=>`kp-draft:${admin?'a':'c'}:${auth.session()?.id||''}`;
const readDraft=()=>{try{const d=JSON.parse(localStorage.getItem(draftKey())||'null');return d&&Date.now()-d.t<6*3600e3?d:null}catch{return null}};
const clearDraft=()=>{try{localStorage.removeItem(draftKey())}catch{}};
window.__kpDraft={read:()=>readDraft()};
function modal(title,body,onSubmit,opts={}){const host=document.getElementById('overlays');host.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${escape(title)}"><div class="row between"><h2>${escape(title)}</h2><button class="icon" id="mclose" aria-label="Fermer">${icon('close')}</button></div>${onSubmit?`<form>${body}<div class="actions"><button class="btn" type="button" id="mcancel">Annuler</button><button class="btn ${opts.danger?'danger-fill':'primary'}" type="submit">${escape(opts.submit||'Enregistrer')}</button></div></form>`:body}</section></div>`;const close=()=>{host.innerHTML='';document.removeEventListener('keydown',key);if(opts.draft)clearDraft()};const key=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const els=[...host.querySelectorAll('button,input,select,textarea,a')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}};document.addEventListener('keydown',key);host.querySelector('#mclose').onclick=close;host.querySelector('#mcancel')?.addEventListener('click',close);host.querySelector('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)close()};if(onSubmit)host.querySelector('form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const sb=e.target.querySelector('[type=submit]');sb.disabled=true;try{await onSubmit(values);close()}catch(err){toast(err.message)}finally{sb.disabled=false}};enhancePasswords(host);
if(opts.draft&&onSubmit&&!document.querySelector('#overlays .modal-backdrop[data-x]')){const form=host.querySelector('form'),d=readDraft();if(d&&d.id===opts.draft&&d.title===title)for(const[k,v]of Object.entries(d.values||{})){const el=form.elements[k];if(el&&el.type!=='file'&&el.type!=='checkbox'&&el.type!=='radio')el.value=v}
let t=0;const save=()=>{clearTimeout(t);t=setTimeout(()=>{if(!form.isConnected)return;try{const values={};for(const[k,v]of new FormData(form))if(typeof v==='string')values[k]=v;localStorage.setItem(draftKey(),JSON.stringify({t:Date.now(),id:opts.draft,title,args:opts.draftArgs||null,values}))}catch{}},250)};form.addEventListener('input',save);form.addEventListener('change',save);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&form.isConnected){clearTimeout(t);t=0;try{const values={};for(const[k,v]of new FormData(form))if(typeof v==='string')values[k]=v;localStorage.setItem(draftKey(),JSON.stringify({t:Date.now(),id:opts.draft,title,args:opts.draftArgs||null,values}))}catch{}}})}
host.querySelector('input,button').focus()}
// Bouton « voir / masquer » sur chaque champ mot de passe.
function enhancePasswords(root){root.querySelectorAll('input[type="password"]:not([data-pw])').forEach(input=>{input.dataset.pw='1';const wrap=document.createElement('span');wrap.className='pw-field';input.replaceWith(wrap);wrap.append(input);const b=document.createElement('button');b.type='button';b.className='pw-toggle';b.setAttribute('aria-label','Afficher le mot de passe');b.innerHTML=icon('eye');b.onclick=()=>{const show=input.type==='password';input.type=show?'text':'password';b.classList.toggle('is-on',show);b.setAttribute('aria-label',show?'Masquer le mot de passe':'Afficher le mot de passe');input.focus()};wrap.append(b)})}
const homeOf=u=>isStaff(u)?'/admin':'/client';
// Page de connexion : un panneau qui change de vue (connexion, création de compte, mot de passe oublié, nouveau mot de passe).
let signupOpen=false;
async function login(user,resetToken){app.innerHTML=`<div class="login"><div class="login-visual"><img src="/img/login.webp?v=2" srcset="/img/login-900.webp?v=2 900w, /img/login.webp?v=2 1596w" sizes="(max-width: 900px) 100vw, 55vw" alt="Portrait d’une petite fille coiffée d’un foulard aux couleurs d’Haïti" fetchpriority="high"></div><main class="login-panel" id="login-panel"></main></div>`;if(resetToken)return resetView(resetToken);if(user?.mustChangePassword)return newPasswordView();if(user?.needsCode)return codeView();try{signupOpen=(await api('/api/auth/options')).signup}catch{}signInView()}
const panel=html=>{const p=document.getElementById('login-panel');p.innerHTML=`${brand()}${html}`;enhancePasswords(p);p.querySelector('input')?.focus();return p};
// Envoi d'un formulaire de la page de connexion : bouton désactivé pendant l'appel, erreur dans un toast.
const submit=(form,fn)=>form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('.primary');btn.disabled=true;try{await fn(Object.fromEntries(new FormData(form)))}catch(err){toast(err.message)}finally{btn.disabled=false}};
function signInView(){const p=panel(`<h1>Connexion</h1><p class="login-intro">Votre espace photo privé : retrouvez, téléchargez et partagez les photos de vos séances, mariages et événements.</p><form id="login-form"><label>E-mail<input name="email" type="email" autocomplete="username" required></label><label>Mot de passe<input name="password" type="password" autocomplete="current-password" required></label><div class="row between"><label class="row small"><input type="checkbox" name="remember"> Se souvenir de moi</label><button type="button" class="text-link" id="forgot">Mot de passe oublié ?</button></div><button class="btn primary">Se connecter ${icon('arrow')}</button></form>${signupOpen?`<p class="login-switch">Pas encore de compte ? <button type="button" class="text-link" id="to-signup">Créer un compte</button></p>`:''}${loginFoot()}`);submit(p.querySelector('form'),async v=>{const u=await auth.signIn(v.email,v.password,v.remember==='on');u.mustChangePassword?newPasswordView():u.needsCode?codeView():location.replace(homeOf(u))});p.querySelector('#forgot').onclick=forgotView;p.querySelector('#to-signup')?.addEventListener('click',signUpView)}
// Studio : l'équipe doit saisir (ou créer, la première fois) le mot de passe du studio avant d'entrer.
function studioView(has){app.innerHTML=`<div class="login"><div class="login-visual"><img src="/img/login.webp?v=2" srcset="/img/login-900.webp?v=2 900w, /img/login.webp?v=2 1596w" sizes="(max-width: 900px) 100vw, 55vw" alt="" fetchpriority="high"></div><main class="login-panel" id="login-panel"></main></div>`;const p=panel(has?`<h1>Studio</h1><p class="login-intro">Entrez le mot de passe de votre studio. Il vous sera redemandé dans 12 heures.</p><form id="studio-form"><label>Mot de passe du studio<input name="password" type="password" autocomplete="off" required></label><button class="btn primary">Ouvrir le studio ${icon('arrow')}</button></form><p class="login-switch"><button type="button" class="text-link" id="studio-forgot">Mot de passe du studio oublié ?</button></p><p class="login-switch"><button type="button" class="text-link" id="studio-out">Me déconnecter</button></p>${loginFoot()}`:`<h1>Mot de passe du studio</h1><p class="login-intro">Créez le mot de passe qui protège votre studio. Il vous sera demandé chaque fois que vous l’ouvrez (toutes les 12 heures). Il doit être différent de votre mot de passe de connexion.</p><form id="studio-form"><label>Votre mot de passe de connexion<input name="login" type="password" autocomplete="current-password" required></label><label>Nouveau mot de passe du studio<input name="password" type="password" autocomplete="new-password" minlength="6" required></label><label>Confirmer<input name="confirm" type="password" autocomplete="new-password" minlength="6" required></label><button class="btn primary">Créer et ouvrir ${icon('arrow')}</button></form><p class="login-switch"><button type="button" class="text-link" id="studio-out">Me déconnecter</button></p>${loginFoot()}`);submit(p.querySelector('form'),async v=>{if(has)await api('/api/auth/studio/unlock',{method:'POST',body:{password:v.password}});else{if(v.password!==v.confirm)throw Error('Les deux mots de passe ne correspondent pas.');await api('/api/auth/studio/password',{method:'POST',body:{login:v.login,password:v.password}})}location.reload()});p.querySelector('#studio-out').onclick=()=>auth.signOut();p.querySelector('#studio-forgot')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;try{const r=await api('/api/auth/studio/forgot',{method:'POST'});toast(r.sent?`Un lien vient d’être envoyé à ${r.email}. Il est valable 1 heure.`:`Le lien est préparé pour ${r.email}, mais l’envoi d’e-mails n’est pas actif sur ce serveur.`)}catch(err){toast(err.message)}finally{b.disabled=false}})}
// Lien reçu par e-mail : choisir un nouveau mot de passe du studio.
function studioResetView(token){app.innerHTML=`<div class="login"><div class="login-visual"><img src="/img/login.webp?v=2" srcset="/img/login-900.webp?v=2 900w, /img/login.webp?v=2 1596w" sizes="(max-width: 900px) 100vw, 55vw" alt="" fetchpriority="high"></div><main class="login-panel" id="login-panel"></main></div>`;const p=panel(`<h1>Nouveau mot de passe du studio</h1><p class="login-intro">Choisissez le mot de passe qui protège votre studio. Il doit être différent de votre mot de passe de connexion.</p><form id="studio-reset-form"><label>Nouveau mot de passe du studio<input name="password" type="password" autocomplete="new-password" minlength="6" required></label><label>Confirmer<input name="confirm" type="password" autocomplete="new-password" minlength="6" required></label><button class="btn primary">Enregistrer et ouvrir ${icon('arrow')}</button></form>${loginFoot()}`);submit(p.querySelector('form'),async v=>{if(v.password!==v.confirm)throw Error('Les deux mots de passe ne correspondent pas.');await api('/api/auth/studio/reset',{method:'POST',body:{token,password:v.password}});try{sessionStorage.removeItem('kp-studio-reset')}catch{}location.replace('/admin')})}
// Client inscrit seul : aucun accès tant qu'il n'a pas saisi le code d'un photographe.
function codeView(){const p=panel(`<h1>Code de votre photographe</h1><p class="login-intro">Pour ouvrir votre espace, entrez le code (2 à 4 lettres ou chiffres) que votre photographe vous a donné.</p><form id="code-form"><label>Code<input name="code" maxlength="4" minlength="2" required autocomplete="off" autocapitalize="characters" spellcheck="false" style="text-transform:uppercase;letter-spacing:.35em;text-align:center;font-size:26px;font-weight:700"></label><button class="btn primary">Ouvrir mon espace ${icon('arrow')}</button></form><p class="login-switch">Pas le bon compte ? <button type="button" class="text-link" id="code-out">Me déconnecter</button></p>${loginFoot()}`);submit(p.querySelector('form'),async v=>{const r=await api('/api/auth/access-code',{method:'POST',body:{code:v.code}});location.replace(homeOf(r.user))});p.querySelector('#code-out').onclick=()=>auth.signOut()}
function signUpView(){const p=panel(`<h1>Créer un compte</h1><form id="signup-form"><label>Nom complet<input name="name" autocomplete="name" required maxlength="120"></label><label>E-mail<input name="email" type="email" autocomplete="email" required></label><label><span>Téléphone <span class="optional">(facultatif)</span></span><input name="phone" type="tel" autocomplete="tel" maxlength="40"></label><label>Mot de passe<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirmer<input name="confirm" type="password" autocomplete="new-password" minlength="8" required></label><label class="row small terms-ok"><input type="checkbox" name="terms" required> <span>J’accepte les <a href="/conditions" target="_blank" rel="noopener">conditions d’utilisation</a></span></label><button class="btn primary">Créer mon compte ${icon('arrow')}</button></form><p class="login-switch">Déjà un compte ? <button type="button" class="text-link" id="to-login">Se connecter</button></p>${loginFoot()}`);submit(p.querySelector('form'),async v=>{if(v.password!==v.confirm)throw Error('Les deux mots de passe ne correspondent pas.');await api('/api/auth/signup',{method:'POST',body:{name:v.name,email:v.email,phone:v.phone,password:v.password}});location.replace('/client')});p.querySelector('#to-login').onclick=signInView}
function forgotView(){const p=panel(`<h1>Mot de passe oublié</h1><form id="forgot-form"><label>E-mail du compte<input name="email" type="email" autocomplete="email" required></label><button class="btn primary">Recevoir un lien ${icon('send')}</button></form><p class="login-switch"><button type="button" class="text-link" id="to-login">← Retour à la connexion</button></p>`);submit(p.querySelector('form'),async v=>{const r=await api('/api/auth/forgot',{method:'POST',body:{email:v.email}});panel(`<h1>Vérifiez vos e-mails</h1><div class="login-note">${icon('mail')}<p>${escape(r.message)} Le lien est valable 1 heure.</p></div><p class="login-switch"><button type="button" class="text-link" id="to-login">← Retour à la connexion</button></p>`).querySelector('#to-login').onclick=signInView});p.querySelector('#to-login').onclick=signInView}
// Lien reçu par e-mail : /login?reset=<jeton>
function resetView(token){const p=panel(`<h1>Nouveau mot de passe</h1><form id="reset-form"><label>Nouveau mot de passe<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirmer<input name="confirm" type="password" autocomplete="new-password" minlength="8" required></label><button class="btn primary">Enregistrer ${icon('arrow')}</button></form>`);submit(p.querySelector('form'),async v=>{if(v.password!==v.confirm)throw Error('Les deux mots de passe ne correspondent pas.');const r=await api('/api/auth/reset',{method:'POST',body:{token,password:v.password}});history.replaceState(null,'','/login');location.replace(homeOf(r.user))})}
// Première connexion avec un mot de passe temporaire : le client choisit le sien.
function newPasswordView(){const p=panel(`<h1>Choisissez votre mot de passe</h1><form id="password-form">${passwordFields('Mot de passe temporaire')}<button class="btn primary">Continuer ${icon('arrow')}</button></form>`);submit(p.querySelector('form'),async v=>{if(v.newPassword!==v.confirm)throw Error('Les deux mots de passe ne correspondent pas.');location.replace(homeOf(await auth.changePassword(v.currentPassword,v.newPassword)))})}
// Accès : tout le site demande une connexion. Seule l'équipe (propriétaire + admins) voit le studio ;
// elle peut aussi ouvrir client.html pour ses propres galeries (« Mes photos »).
// Le serveur applique les mêmes règles (server/src/routes/pages.js) et l'API vérifie chaque requête.
async function start(){const sr=new URLSearchParams(location.search).get('studio-reset');if(sr){try{sessionStorage.setItem('kp-studio-reset',sr)}catch{}history.replaceState(null,'',location.pathname)}const user=await auth.load();if(admin&&user?.role==='admin')for(const l of['Team','Settings'])labels.includes(l)&&labels.splice(labels.indexOf(l),1);if(location.pathname.includes('login')||document.body.dataset.page==='login'){const reset=new URLSearchParams(location.search).get('reset');if(reset)return login(user,reset);if(user&&!user.mustChangePassword&&!user.needsCode)return location.replace(homeOf(user));return login(user)}if(!user||user.mustChangePassword||user.needsCode)return location.replace('/login');const previewId=new URLSearchParams(location.search).get('preview');if(!admin&&isStaff(user)&&previewId){try{preview=await service.loadPreview(previewId)}catch(e){app.innerHTML=`<main class="main">${empty('Aperçu impossible.')}</main>`;return toast(e.message)}initFaq(()=>service.data.photographers);return render()}if(admin&&!isStaff(user))return location.replace('/client');if(!admin)initFaq(()=>service.data.photographers);if(admin){const st=await api('/api/auth/studio').catch(()=>null);let tok=null;try{tok=sessionStorage.getItem('kp-studio-reset')}catch{}if(st&&tok)return studioResetView(tok);if(st&&!st.unlocked)return studioView(st.hasPassword)}try{await service.load(admin?'admin':'client')}catch(e){app.innerHTML=`<main class="main">${empty('Impossible de charger vos données.')}</main>`;return toast(e.message)}restoreNav();render();restoreScroll()}
// ----- Expiration de la galerie -----
function expiryNote(e){if(!e.expiresAt)return'';const days=Math.ceil((Date.parse(e.expiresAt+'T23:59:59Z')-Date.now())/864e5);const d=new Date(e.expiresAt+'T12:00:00Z').toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});const soon=days<=7;return `<p class="expiry-note${soon?' soon':''}">${icon('clock')} ${soon?`Disponible encore ${days<=0?'aujourd’hui':days===1?'jusqu’à demain':days+' jours'} : pensez à télécharger vos photos.`:`Disponible jusqu’au ${d}`}</p>`}

// ----- Partage famille : lien + mot de passe, lecture seule -----
// Partage famille : même fenêtre que dans le studio (js/sharelinks.js).
function openShare(e){if(!e)return;openShareManager({event:e,base:'/api/client',canDl:!!service.data.permissions.share_download&&e.download,modal,toast})}

// ----- Espace « Commentaires » du client : les mots de sa famille (liens de partage) -----
let familyGallery='';
function bindFamily(){const list=document.getElementById('family-list');if(!list||preview)return list&&(list.innerHTML=empty('Aperçu : les commentaires de la famille restent privés.'));
api('/api/client/comments').then(r=>{if(!list.isConnected)return;const all=r.comments;
const gals=[...new Map(all.map(c=>[c.event.id,c.event.name])).entries()];if(!gals.some(([id])=>id===familyGallery))familyGallery='';
const filters=document.getElementById('family-filters');
filters.innerHTML=gals.length>1?`<div class="filterbar family-bar"><button class="chip ${familyGallery?'':'active'}" data-fg="">Toutes <small>${all.length}</small></button>${gals.map(([id,name])=>`<button class="chip ${familyGallery===id?'active':''}" data-fg="${id}">${escape(name)} <small>${all.filter(c=>c.event.id===id).length}</small></button>`).join('')}</div>`:'';
filters.querySelectorAll('[data-fg]').forEach(b=>b.onclick=()=>{familyGallery=b.dataset.fg;bindFamily()});
const shown=all.filter(c=>!familyGallery||c.event.id===familyGallery);
if(!all.length){list.innerHTML=`<div class="empty family-empty">${icon('chat')}<h2>${r.links?'Aucun commentaire pour le moment':'Partagez une galerie avec votre famille'}</h2><p class="small">${r.links?'Dès que votre famille écrit un mot sous une photo, il apparaît ici.':'Ouvrez une galerie, touchez « Partager », et envoyez le lien avec son mot de passe : votre famille pourra commenter vos photos.'}</p>${r.links?'':`<button class="btn primary" data-nav="Events">${icon('share')} Choisir une galerie</button>`}</div>`;list.querySelector('[data-nav]')?.addEventListener('click',()=>navigate('Events'));return}
list.innerHTML=`<div class="family-list">${shown.map(c=>`<article class="family-item"><button class="family-thumb" data-fopen="${c.id}" aria-label="Voir la photo N° ${c.photo.number}"><img src="${escape(c.photo.thumb)}" alt="" loading="lazy"><span>N° ${c.photo.number}</span></button><div class="family-main"><p class="family-meta"><span class="family-avatar">${escape(initials(c.author.name))}</span><strong>${escape(c.author.name)}</strong><span class="badge is-draft">Famille${c.author.via?` · ${escape(c.author.via)}`:''}</span><time datetime="${c.date}">${ago(c.date)}</time></p><p class="family-body">${escape(c.body).replace(/\n/g,'<br>')}</p><p class="family-where">${escape(c.event.name)} · photo N° ${c.photo.number}</p><div class="family-actions"><button class="text-link" data-fopen="${c.id}">${icon('eye')} Voir la photo</button><button class="text-link danger" data-fdel="${c.id}">${icon('trash')} Supprimer</button></div></div></article>`).join('')}</div>`;
list.querySelectorAll('[data-fopen]').forEach(b=>b.onclick=()=>{const c=all.find(x=>x.id===b.dataset.fopen);openNotification({kind:'comment',eventId:c.event.id,photoId:c.photo.id})});
list.querySelectorAll('[data-fdel]').forEach(b=>b.onclick=()=>modal('Supprimer le commentaire','<p>Ce mot de votre famille sera supprimé définitivement.</p>',async()=>{await api(`/api/client/comments/${b.dataset.fdel}`,{method:'DELETE'});toast('Commentaire supprimé.');bindFamily()},{submit:'Supprimer',danger:true}))}).catch(e=>{list.innerHTML=empty('Impossible de charger les commentaires.');toast(e.message)})}

// ----- Application installable (PWA) -----
let installPrompt=null;
const standalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const isIos=()=>/iphone|ipad|ipod/i.test(navigator.userAgent)&&!window.MSStream;
// Application déjà installée sur cet appareil : on s'en souvient, et les boutons « Installer » disparaissent
// partout (même dans un onglet du navigateur). Si elle est désinstallée, le navigateur repropose l'installation.
const INSTALLED_KEY='kp-installed';
const installedFlag=()=>{try{return localStorage.getItem(INSTALLED_KEY)==='1'}catch{return false}};
const markInstalled=on=>{try{on?localStorage.setItem(INSTALLED_KEY,'1'):localStorage.removeItem(INSTALLED_KEY)}catch{}};
const installed=()=>standalone()||installedFlag();
const hideInstall=()=>document.querySelectorAll('[data-install],#install-card').forEach(el=>el.remove());
if(standalone())markInstalled(true);
navigator.getInstalledRelatedApps?.().then(apps=>{if(apps.length){markInstalled(true);hideInstall()}}).catch(()=>{});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;const was=installedFlag();markInstalled(false);if(document.getElementById('install-card')||(was&&auth.session()))render()});
window.addEventListener('appinstalled',()=>{installPrompt=null;markInstalled(true);hideInstall();toast('KentraPix est installé sur votre appareil.')});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
// Thème clair / sombre (js/theme.js) : auto = suit le réglage du téléphone / de l’ordinateur.
function themeSwitch(){const cur=window.kpTheme?.get()||'light';return `<div class="theme-switch" role="radiogroup" aria-label="Thème">${[['light','sun','Clair'],['dark','moon','Sombre'],['auto','monitor','Auto']].map(([v,i,l])=>`<button type="button" role="radio" aria-checked="${cur===v}" class="${cur===v?'active':''}" data-theme-set="${v}">${icon(i)}${l}</button>`).join('')}</div>`}
function bindTheme(){document.querySelectorAll('[data-theme-set]').forEach(b=>b.onclick=()=>{window.kpTheme?.set(b.dataset.themeSet);render()});const t=document.getElementById('theme-toggle');if(t)t.onclick=()=>{window.kpTheme?.set(document.documentElement.dataset.theme==='dark'?'light':'dark');render()}}
function installCard(){if(installed())return'';if(installPrompt||!isIos())return `<div class="install-card" id="install-card">${icon('phone')}<div><strong>Installer KentraPix</strong><p class="small">Retrouvez vos photos depuis l’écran d’accueil, comme une application.</p></div><button class="btn primary" id="install-app">Installer</button></div>`;if(isIos())return `<div class="install-card" id="install-card">${icon('phone')}<div><strong>Installer KentraPix</strong><p class="small">Dans Safari, touchez ${icon('share')} <b>Partager</b>, puis <b>Sur l’écran d’accueil</b>.</p></div></div>`;return''}
// Installer : la fenêtre du navigateur si elle est prête (Chrome, Edge, Android), sinon le mode d'emploi de l'appareil.
async function installApp(){if(standalone())return toast('KentraPix est déjà installé sur cet appareil.');if(installPrompt){installPrompt.prompt();const c=await installPrompt.userChoice.catch(()=>null);installPrompt=null;if(c?.outcome==='accepted')toast('Installation en cours…');if(auth.session())render();return}openInstallHelp()}
/** Petite icône d'installation (infobulle « Installer l'application ») ; rien si l'application est déjà installée. */
function installButton(cls='mini-install'){return installed()?'':`<button type="button" class="${cls}" data-install title="Installer l’application" aria-label="Installer l’application">${icon('download')}</button>`}
const loginFoot=()=>`<div class="login-foot"><p>${installButton()}© ${new Date().getFullYear()} KentraPix. Tous droits réservés. · <a href="/conditions" target="_blank" rel="noopener">Conditions d’utilisation</a></p></div>`;
function platform(){const ua=navigator.userAgent;if(isIos())return'ios';if(/android/i.test(ua))return'android';if(/firefox/i.test(ua))return'firefox';if(/safari/i.test(ua)&&!/chrome|chromium|edg/i.test(ua))return'safari';return'desktop'}
function openInstallHelp(){const cur=platform();const steps={
desktop:['Ordinateur (Chrome ou Edge)',`Cliquez sur l’icône ${icon('download')} <b>Installer</b> à droite de la barre d’adresse.`,'Ou ouvrez le menu <b>⋮</b> (Chrome) / <b>…</b> (Edge), puis <b>Installer KentraPix</b> (parfois sous « Caster, enregistrer et partager » ou « Applications »).','KentraPix s’ouvre ensuite dans sa propre fenêtre, depuis le menu Démarrer ou le Bureau.'],
safari:['Mac (Safari)','Menu <b>Fichier</b> → <b>Ajouter au Dock</b>.','KentraPix apparaît dans le Dock, comme une application.'],
firefox:['Firefox','Firefox n’installe pas les applications web.','Ouvrez ce site avec <b>Chrome</b> ou <b>Edge</b> pour l’installer.'],
ios:['iPhone et iPad (Safari)',`Touchez ${icon('share')} <b>Partager</b> en bas de l’écran.`,'Choisissez <b>Sur l’écran d’accueil</b>, puis <b>Ajouter</b>.'],
android:['Android (Chrome)','Touchez le menu <b>⋮</b> en haut à droite.','Choisissez <b>Installer l’application</b> (ou « Ajouter à l’écran d’accueil »).']};
const block=([title,...lines],on)=>`<section class="install-step${on?' is-current':''}"><h3>${on?`${icon('check')} `:''}${title}</h3><ol>${lines.map(l=>`<li>${l}</li>`).join('')}</ol></section>`;
modal('Installer KentraPix',`<div class="install-help"><p class="small">Gardez KentraPix sur votre ordinateur ou votre téléphone, comme une vraie application : une icône, sa propre fenêtre, et vos photos en un clic.</p>${block(steps[cur],true)}<details><summary>Autres appareils</summary>${Object.entries(steps).filter(([k])=>k!==cur&&k!=='firefox').map(([,v])=>block(v,false)).join('')}</details></div>`)}
document.addEventListener('click',e=>{if(e.target.closest?.('[data-install]')){e.preventDefault();installApp()}});
start();
